-- Test fixture: 12 round 1 questions released to the beta. Generated by pipeline/release_round.sh; test use only.
BEGIN;
INSERT INTO item (id, status, calibration_core, current_version) VALUES ('15abe5b8-e32a-9e7b-c3c4-27543ae72591', 'live', true, 1)
  ON CONFLICT (id) DO NOTHING;
INSERT INTO item_version (item_id, version, stem, lead_in, options, key, explanations, learning_point, rural_note,
  learning_area, secondary_areas, domains, presentation, context, cognitive_level, patient, target_difficulty,
  jurisdiction, provenance, generation, "references", tutor_context, review_level, reviewed_by, review_by, supersedes,
  pgy_level, clinical_experiences, setting)
SELECT '15abe5b8-e32a-9e7b-c3c4-27543ae72591', 1, 'You are the resident covering the wards overnight at a 30-bed regional hospital in South Australia''s Mid North, 2 hours by road from Adelaide. The physician is available by phone. At 22:30 the nurse asks you to see a 32-year-old Aboriginal man admitted two days ago with lower-leg cellulitis. He has had 48 hours of intravenous flucloxacillin, is afebrile with observations in the normal range, and the erythema is receding behind the marked line. He has just learned that his uncle has died in Port Augusta and tells you he must leave tonight to travel there for Sorry Business. He is calm and clearly understands that his infection is not yet fully treated. He has a mobile phone and family will drive him.', 'What is the most appropriate response?', '[{"id":"A","text":"Explain that he must remain until the intravenous course is finished and document that he was advised not to leave tonight"},{"id":"B","text":"Acknowledge his obligation, review for oral antibiotics and arrange Port Augusta follow-up agreed with the physician"},{"id":"C","text":"Ask him to sign the discharge against medical advice form so that he can leave tonight without further delay"},{"id":"D","text":"Suggest that his family travel to the hospital instead, so that he can grieve here while completing his treatment"}]'::jsonb, 'B', '{"A":"Insisting he stay ignores a cultural obligation that is central to his wellbeing and his standing in his community. He has capacity and will leave regardless; the doctor''s job is to make that departure as safe as possible, not to refuse to plan for it.","B":"Attending Sorry Business is a recognised cultural obligation, not an inconvenience. He is clinically improving and meets usual criteria for intravenous-to-oral switch, so a planned early discharge on oral antibiotics with a review arranged through an Aboriginal health service near where he will be, written instructions on return precautions and a brief phone call to the physician on call is the safest and most culturally responsive plan.","C":"Treating this as discharge against medical advice frames a reasonable decision as non-compliance and often ends with no antibiotics, no follow-up and no handover. The form does not remove the duty to arrange safe ongoing care.","D":"Asking the family to come to him misunderstands Sorry Business, which involves travelling to be with community for ceremony; it is not something that can be relocated to the ward."}'::jsonb,
  'When a patient must leave for Sorry Business, plan a safe early discharge (oral switch, follow-up near their destination, return advice) rather than framing the departure as non-compliance.', 'In a regional hospital without an on-site Aboriginal Liaison Officer overnight, the resident may need to make the follow-up arrangements directly, contacting the Aboriginal Community Controlled Health Service or hospital at the destination town and handing over by phone; in a tertiary hospital the Aboriginal Liaison Officer or Aboriginal Health Practitioner would usually coordinate this.', 'Aboriginal and Torres Strait Islander health', ARRAY['Infection and sepsis','Discharge planning','Rural and remote']::text[], ARRAY['1.3','3.3','3.6']::text[],
  'Sorry Business and cultural obligations', 'after_hours', 'management', '{"age_band":"25-44","sex":"male","indigenous":true}'::jsonb, 3,
  'national', 'ai', NULL, '[{"source":"etg","title":"Therapeutic Guidelines: Antibiotic","locator":"Cellulitis and erysipelas; intravenous to oral switch","supports":"key"},{"source":"sa_health","title":"SA Health Aboriginal Health Care Framework and Aboriginal Patient Pathway Officer guidance","locator":"Culturally responsive care; Sorry Business","supports":"key"}]'::jsonb,
  'Key facts: Sorry Business describes the period of mourning and the ceremonial and family obligations following a death; attending is a serious obligation. Cellulitis improving after 48 hours of intravenous therapy in an afebrile patient meets usual oral-switch criteria. Common misconception: that a patient who leaves before planned completion of therapy must be processed as discharge against medical advice. Out of scope: specific antibiotic choice and dosing for the oral switch, and the hospital''s leave-of-absence paperwork.', 'none', ARRAY[]::text[], NULL, NULL,
  'both', ARRAY['A']::text[], 'rural'
  
ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO item (id, status, calibration_core, current_version) VALUES ('49ec713d-7167-c7b9-359d-a9543343b7a5', 'live', true, 1)
  ON CONFLICT (id) DO NOTHING;
INSERT INTO item_version (item_id, version, stem, lead_in, options, key, explanations, learning_point, rural_note,
  learning_area, secondary_areas, domains, presentation, context, cognitive_level, patient, target_difficulty,
  jurisdiction, provenance, generation, "references", tutor_context, review_level, reviewed_by, review_by, supersedes,
  pgy_level, clinical_experiences, setting)
SELECT '49ec713d-7167-c7b9-359d-a9543343b7a5', 1, 'You are the PGY2 on the general ward of a 30-bed regional hospital in South Australia''s Mid North, 2 hours by road from Adelaide. The visiting physician has reviewed a 19-year-old Aboriginal woman admitted two days ago with community-acquired pneumonia and has agreed she can go home tomorrow. She has known rheumatic heart disease with moderate mitral regurgitation and is prescribed 4-weekly intramuscular benzathine benzylpenicillin as secondary prophylaxis; the medication chart and the hospital record show her last injection was seven weeks ago, and she says the clinic she usually attends has closed. She has no current GP, her last echocardiogram was 10 months ago and she mentions she is overdue for a dental check. You have a long task list before the end of the day.', 'Which task is the most important to complete before she leaves hospital?', '[{"id":"A","text":"Book an outpatient dental check-up for her through the regional public dental health service"},{"id":"B","text":"Request a follow-up chest X-ray in six weeks'' time to confirm that her pneumonia has fully resolved"},{"id":"C","text":"Give the overdue benzathine benzylpenicillin today and notify the rheumatic heart disease register"},{"id":"D","text":"Arrange her next surveillance echocardiogram for 12 months after her previous echocardiogram"}]'::jsonb, 'C', '{"A":"Dental health matters in rheumatic heart disease because of endocarditis risk, but a routine dental review can be organised after discharge; it does not carry the immediate risk that a lapse in secondary prophylaxis does.","B":"Follow-up imaging after pneumonia is reasonable in selected patients but is a low-urgency task that can be requested through her future GP.","C":"Each missed or late benzathine benzylpenicillin dose exposes her to recurrence of acute rheumatic fever, which worsens valve damage; she is already three weeks overdue. Giving the dose in hospital today and informing the rheumatic heart disease register and control program, so they can re-establish her recall and link her to a new clinic, is the highest-value action and is within a PGY2''s scope.","D":"Echocardiographic surveillance is important but is not due for another two months; it can be requested in the discharge plan rather than before she leaves."}'::jsonb,
  'For a patient with rheumatic heart disease, maintaining secondary benzathine benzylpenicillin prophylaxis and keeping the rheumatic heart disease register informed takes priority over routine surveillance tasks.', 'In a regional hospital the resident may be the only clinician who notices the lapse; the SA Rheumatic Heart Disease Control Program can be contacted directly to re-establish recall and identify a local clinic or Aboriginal health service that can give ongoing injections.', 'Aboriginal and Torres Strait Islander health', ARRAY['Chronic disease, prevention and advocacy','Discharge planning','Rural and remote']::text[], ARRAY['1.3','4.4','2.8']::text[],
  'acute rheumatic fever and rheumatic heart disease', 'ward', 'prioritisation', '{"age_band":"16-24","sex":"female","indigenous":true}'::jsonb, 2,
  'national', 'ai', NULL, '[{"source":"other","title":"The 2020 Australian guideline for prevention, diagnosis and management of acute rheumatic fever and rheumatic heart disease (RHDAustralia)","locator":"Secondary prophylaxis; register and control programs","supports":"key"},{"source":"sa_health","title":"SA Health Rheumatic Heart Disease Control Program","locator":"Notification and recall","supports":"key"}]'::jsonb,
  'Key facts: secondary prophylaxis with benzathine benzylpenicillin every 4 weeks (or 3-weekly in selected high-risk patients) is the single most effective intervention to prevent recurrence and progression of rheumatic heart disease; adherence above about 80 percent of doses is needed. Hospital admission is an opportunity to give an overdue dose. SA has an RHD register and control program under the Public Health Act notification system. Common misconception: that prophylaxis is managed by the register and is not the admitting team''s concern. Out of scope: anticoagulation and surgical timing for valve disease.', 'none', ARRAY[]::text[], NULL, NULL,
  'PGY2', ARRAY['B']::text[], 'rural'
  
ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO item (id, status, calibration_core, current_version) VALUES ('eed626a7-f496-5f1f-4c05-c1fb9f80be13', 'live', true, 1)
  ON CONFLICT (id) DO NOTHING;
INSERT INTO item_version (item_id, version, stem, lead_in, options, key, explanations, learning_point, rural_note,
  learning_area, secondary_areas, domains, presentation, context, cognitive_level, patient, target_difficulty,
  jurisdiction, provenance, generation, "references", tutor_context, review_level, reviewed_by, review_by, supersedes,
  pgy_level, clinical_experiences, setting)
SELECT 'eed626a7-f496-5f1f-4c05-c1fb9f80be13', 1, 'You are the PGY2 on a general medical ward of a tertiary hospital in Adelaide. On the morning ward round the team reviews a 31-year-old Aboriginal woman from a remote community who was admitted overnight with pyelonephritis. She is clinically improving. During the review she looks at the floor, gives brief answers, and says "yeah" when the registrar asks whether she understands that she will need to stay for intravenous antibiotics and whether she has any questions. Afterwards the registrar remarks that she seems "disengaged and probably won''t comply" and asks you to document that she has been counselled and agrees with the plan. The ward''s Aboriginal Liaison Officer has not yet been told she is an inpatient.', 'Which interpretation of her responses is most appropriate?', '[{"id":"A","text":"Her brief answers may reflect communication norms or feeling unsafe, so her understanding and agreement cannot be assumed"},{"id":"B","text":"Her responses show she understands the plan and consents to it, so documenting her agreement is appropriate"},{"id":"C","text":"Her quiet presentation most likely indicates depression, and a mental health assessment should be requested"},{"id":"D","text":"Her lack of engagement suggests intoxication or withdrawal, which should be assessed before any further discussion with her"}]'::jsonb, 'A', '{"A":"For many Aboriginal people, direct eye contact and extended conversation with unfamiliar authority figures on a crowded ward round are uncomfortable, and \"yeah\" may be a polite acknowledgement rather than informed agreement. The safe approach is to return later, sit with her, use open questions and allow silence, offer the Aboriginal Liaison Officer, and ask about family involvement before documenting that she understands.","B":"Documenting agreement on the basis of a monosyllabic reply during a team ward round risks recording consent that was never truly given, which is both a communication failure and a documentation error.","C":"Depression is a possible contributor in any inpatient but there is nothing here to support it over the more likely explanation; leaping to a psychiatric label is itself a form of bias.","D":"There is no clinical information suggesting intoxication or withdrawal; attributing a quiet manner to substance use is a stereotype that contributes to inequitable care."}'::jsonb,
  'Quiet, brief answers from an Aboriginal patient during a ward round are not evidence of understanding, agreement or disengagement; check understanding one-to-one, with the Aboriginal Liaison Officer and family where wanted.', 'In a tertiary hospital the Aboriginal Liaison Officer service is usually available each weekday and should be notified of every Aboriginal inpatient; in a regional hospital the resident may need to call the Aboriginal health team or a local Aboriginal health service directly.', 'Aboriginal and Torres Strait Islander health', ARRAY['Communication, handover and consent','Documentation']::text[], ARRAY['1.3','3.4','1.2']::text[],
  'culturally safe communication', 'ward', 'interpretation', '{"age_band":"25-44","sex":"female","indigenous":true}'::jsonb, 3,
  'national', 'ai', NULL, '[{"source":"acsqhc","title":"National Safety and Quality Health Service Standards (2nd edition), User guide for Aboriginal and Torres Strait Islander health","locator":"Action 1.33 and 2.8; culturally safe communication","supports":"key"},{"source":"mba","title":"Medical Board of Australia, Good medical practice: a code of conduct for doctors in Australia","locator":"Section 4.7 Aboriginal and Torres Strait Islander health and cultural safety","supports":"key"}]'::jsonb,
  'Key facts: cultural safety is defined by the patient''s experience, not the clinician''s intent. Gratuitous concurrence (agreeing to be polite or to end an uncomfortable exchange) is well described. Good practice includes introducing yourself, sitting down, open questions, comfortable silence, asking who she wants involved, and notifying the Aboriginal Liaison Officer on admission. Common misconception: that labels like "non-compliant" are clinical observations rather than judgements. Out of scope: antibiotic choice for pyelonephritis.', 'none', ARRAY[]::text[], NULL, NULL,
  'PGY2', ARRAY['A']::text[], 'metro'
  
ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO item (id, status, calibration_core, current_version) VALUES ('ee16ca5a-0549-ae39-7cc2-51aa05ee7c39', 'live', true, 1)
  ON CONFLICT (id) DO NOTHING;
INSERT INTO item_version (item_id, version, stem, lead_in, options, key, explanations, learning_point, rural_note,
  learning_area, secondary_areas, domains, presentation, context, cognitive_level, patient, target_difficulty,
  jurisdiction, provenance, generation, "references", tutor_context, review_level, reviewed_by, review_by, supersedes,
  pgy_level, clinical_experiences, setting)
SELECT 'ee16ca5a-0549-ae39-7cc2-51aa05ee7c39', 1, 'You are the junior doctor on the surgical ward of a country hospital 90 minutes from the nearest tertiary centre; overnight you cover the ward and the emergency department alone, with the surgeon on call by phone. A 56-year-old Aboriginal man is day one after an open appendicectomy. When you ask how he is, he says he is "alright" and does not ask for anything. The nurse tells you he has not got out of bed, grimaces when he moves, has declined the charted oxycodone twice and has not eaten. His nephew, who is visiting, says quietly that "Uncle won''t complain, he never does". Observations are normal apart from a heart rate of 102 beats per minute.', 'Which interpretation of this situation is most appropriate?', '[{"id":"A","text":"He is experiencing little pain, and his analgesia can now be stepped down to paracetamol alone"},{"id":"B","text":"He is declining opioids because of a probable history of substance misuse that should be clarified"},{"id":"C","text":"His answer may understate his pain, which should be assessed by function, behaviour and a suitable scale"},{"id":"D","text":"His nephew is influencing his answers and so should be asked to leave the room during clinical assessments"}]'::jsonb, 'C', '{"A":"Immobility, grimacing, poor intake and tachycardia all point to uncontrolled pain despite the reassuring words; stepping down analgesia would compound the problem and raise his risk of complications such as atelectasis and venous thromboembolism.","B":"There is nothing in the history to suggest substance misuse. Assuming it is a stereotype; the more likely reasons for declining are stoicism, not wanting to be a bother, concern about what the tablets are for, or previous experience of being dismissed.","C":"Under-reporting of pain is common and may reflect stoicism, cultural norms around men''s health, mistrust or unfamiliarity with hospital routines. Observing behaviour and function, using a pain tool he can relate to, explaining what the medication is and why it will help him recover, and involving his nephew if he wishes gives a truer picture and better care.","D":"The nephew is offering useful insight and his presence is likely to make the patient feel safer; excluding family undermines trust and is contrary to culturally safe practice."}'::jsonb,
  'A patient who says he is "alright" but shows behavioural and physiological signs of pain needs his pain assessed by function and observation, not accepted at face value.', 'In a country hospital there is usually no acute pain service and no on-site Aboriginal Liaison Officer overnight, so the junior doctor and nursing staff carry the assessment themselves and should document their approach for the morning team.', 'Aboriginal and Torres Strait Islander health', ARRAY['Surgery and perioperative care','Communication, handover and consent']::text[], ARRAY['1.3','3.6','1.4']::text[],
  'culturally safe communication', 'ward', 'interpretation', '{"age_band":"45-64","sex":"male","indigenous":true}'::jsonb, 2,
  'national', 'ai', NULL, '[{"source":"etg","title":"Therapeutic Guidelines: Analgesic","locator":"Assessment of acute pain","supports":"key"},{"source":"acsqhc","title":"National Safety and Quality Health Service Standards, User guide for Aboriginal and Torres Strait Islander health","locator":"Partnering with consumers; culturally safe care","supports":"key"}]'::jsonb,
  'Key facts: self-report is the gold standard for pain but must be elicited in a way the patient trusts; behavioural indicators (guarding, immobility, poor intake) and physiological signs (tachycardia) support the assessment. Family and the Aboriginal Liaison Officer can help a patient express needs. Common misconception: that declining opioids signals misuse. Out of scope: opioid dosing and multimodal regimen details.', 'none', ARRAY[]::text[], NULL, NULL,
  'both', ARRAY['D']::text[], 'rural'
  
ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO item (id, status, calibration_core, current_version) VALUES ('6b91461d-a59d-054b-12f5-b90456c1858a', 'live', true, 1)
  ON CONFLICT (id) DO NOTHING;
INSERT INTO item_version (item_id, version, stem, lead_in, options, key, explanations, learning_point, rural_note,
  learning_area, secondary_areas, domains, presentation, context, cognitive_level, patient, target_difficulty,
  jurisdiction, provenance, generation, "references", tutor_context, review_level, reviewed_by, review_by, supersedes,
  pgy_level, clinical_experiences, setting)
SELECT '6b91461d-a59d-054b-12f5-b90456c1858a', 1, 'You are the PGY2 on a busy medical ward of a metropolitan general hospital, with a registrar on site overnight. You are making a planned telehealth follow-up call to a 20-year-old Aboriginal man who left the ward two days ago, before completing intravenous antibiotics for a leg cellulitis, after signing a discharge against medical advice form. He explains that he had to go home to look after his younger siblings. The leg is still red and sore but he is not febrile. He asks whether he is "still allowed" to come back to the hospital, or whether he has to go somewhere else now because he signed the form.', 'Which statement correctly describes his entitlement to care after a discharge against medical advice?', '[{"id":"A","text":"The signed form ends the hospital''s duty of care, so he must now present to a general practitioner or a different hospital"},{"id":"B","text":"His right to care and the hospital''s duty of care continue unchanged, and he can return to this hospital at any time"},{"id":"C","text":"He may return only if he is formally readmitted under the original consultant and agrees to complete the intravenous course"},{"id":"D","text":"Because he left with an untreated infection, he can be detained under the Mental Health Act 2009 if he refuses to return"}]'::jsonb, 'B', '{"A":"A discharge against medical advice form documents that risks were explained; it does not waive the patient''s entitlement to care or the hospital''s ongoing duty of care, and it must never be used to refuse a patient who re-presents.","B":"Leaving against advice is a decision by a person with capacity, often for reasons such as caring responsibilities. The duty of care continues: the team should welcome his return, offer oral therapy or hospital-in-the-home if clinically reasonable, arrange review, and involve the Aboriginal Liaison Officer to address the barriers that led him to leave.","C":"Conditions such as mandatory readmission or an all-or-nothing treatment plan are not legal requirements and are likely to drive him away again; a negotiated plan is safer.","D":"The Mental Health Act 2009 (SA) applies only where a person appears to have a mental illness and meets the criteria for an inpatient treatment order; refusing medical treatment for an infection is not grounds for detention."}'::jsonb,
  'A discharge against medical advice form does not end the patient''s entitlement to care; the team should actively offer a plan the patient can accept and make return easy.', '', 'Aboriginal and Torres Strait Islander health', ARRAY['Professionalism, ethics and law','Telehealth','Discharge planning']::text[], ARRAY['1.3','2.1','3.6']::text[],
  'discharge against medical advice', 'telehealth', 'recall', '{"age_band":"16-24","sex":"male","indigenous":true}'::jsonb, 3,
  'national', 'ai', NULL, '[{"source":"mba","title":"Medical Board of Australia, Good medical practice: a code of conduct for doctors in Australia","locator":"Sections 3.3 (informed consent, right to refuse) and 4.7 (cultural safety)","supports":"key"},{"source":"acsqhc","title":"Australian Charter of Healthcare Rights (2nd edition)","locator":"Access and partnership","supports":"key"}]'::jsonb,
  'Key facts: Aboriginal patients leave hospital against advice at several times the rate of non-Indigenous patients, often because of family obligations, feeling unsafe or poor communication; this is a system problem to address, not a patient failing. Good practice on discharge against advice includes offering medications and follow-up, documenting capacity and the discussion, and notifying the Aboriginal Liaison Officer. Common misconception: that the signed form transfers all responsibility to the patient. Out of scope: criteria for a Mental Health Act inpatient treatment order.', 'none', ARRAY[]::text[], NULL, NULL,
  'PGY2', ARRAY['A']::text[], 'metro'
  
ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO item (id, status, calibration_core, current_version) VALUES ('93617cce-bd06-a949-ae34-b1a8999775e4', 'live', true, 1)
  ON CONFLICT (id) DO NOTHING;
INSERT INTO item_version (item_id, version, stem, lead_in, options, key, explanations, learning_point, rural_note,
  learning_area, secondary_areas, domains, presentation, context, cognitive_level, patient, target_difficulty,
  jurisdiction, provenance, generation, "references", tutor_context, review_level, reviewed_by, review_by, supersedes,
  pgy_level, clinical_experiences, setting)
SELECT '93617cce-bd06-a949-ae34-b1a8999775e4', 1, 'You are the intern in the emergency department of a metropolitan general hospital, with the medical registrar on site overnight. A 36-year-old Aboriginal man has presented with two hours of central chest pain. His ECG shows ST depression in the lateral leads and the registrar has told you he will be admitted for serial troponins and likely angiography. When you return to explain the plan, he says he wants his aunty, who raised him and has just arrived in the waiting room, to be with him and part of any decisions. His wife is at home with their children and he has not asked for her to be called. He is alert, with capacity, and in no distress.', 'What is the most appropriate action?', '[{"id":"A","text":"Explain that only his wife, as legal next of kin, can be involved in discussions about his care"},{"id":"B","text":"Explain that hospital policy limits clinical discussions to the patient alone while he is in the emergency department"},{"id":"C","text":"Delay the discussion until the social worker has clarified the family structure in the morning"},{"id":"D","text":"Ask him whom he would like involved and, with his consent, bring his aunty in to join the discussion of the plan"}]'::jsonb, 'D', '{"A":"A patient with capacity chooses who is involved in his care; the \"next of kin\" concept has no legal force here and does not override his wishes. In many Aboriginal families an aunty or grandmother has a central role regardless of the formal relationship.","B":"No such policy exists, and inventing one damages trust at the moment he most needs support; family presence is usually possible in an emergency department cubicle.","C":"Delaying a straightforward request until business hours leaves him without support during a frightening admission; the social worker is not needed to honour his choice.","D":"Asking who he wants involved respects his autonomy and kinship structure, supports culturally safe care and improves understanding of the plan. The patient''s consent to share information is what matters, and it should be documented."}'::jsonb,
  'Ask Aboriginal patients who they want involved in their care and include those people with the patient''s consent, whatever the formal family relationship.', '', 'Aboriginal and Torres Strait Islander health', ARRAY['Communication, handover and consent','Emergency presentations']::text[], ARRAY['1.3','3.6','1.2']::text[],
  'family and kinship in decision-making', 'ed', 'management', '{"age_band":"25-44","sex":"male","indigenous":true}'::jsonb, 1,
  'national', 'ai', NULL, '[{"source":"mba","title":"Medical Board of Australia, Good medical practice: a code of conduct for doctors in Australia","locator":"Sections 3.2 (good patient care) and 4.7 (cultural safety)","supports":"key"},{"source":"acsqhc","title":"National Safety and Quality Health Service Standards, User guide for Aboriginal and Torres Strait Islander health","locator":"Partnering with consumers","supports":"key"}]'::jsonb,
  'Key facts: kinship structures in Aboriginal families often place decision-making support with extended family; a competent adult decides who is involved and what is shared. The legal substitute decision-maker hierarchy only applies when capacity is lost. Common misconception: that a spouse must be consulted first. Out of scope: acute coronary syndrome management.', 'none', ARRAY[]::text[], NULL, NULL,
  'PGY1', ARRAY['C']::text[], 'any'
  
ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO item (id, status, calibration_core, current_version) VALUES ('d1c44202-acf6-7f8d-44ad-2c4bd5032625', 'live', true, 1)
  ON CONFLICT (id) DO NOTHING;
INSERT INTO item_version (item_id, version, stem, lead_in, options, key, explanations, learning_point, rural_note,
  learning_area, secondary_areas, domains, presentation, context, cognitive_level, patient, target_difficulty,
  jurisdiction, provenance, generation, "references", tutor_context, review_level, reviewed_by, review_by, supersedes,
  pgy_level, clinical_experiences, setting)
SELECT 'd1c44202-acf6-7f8d-44ad-2c4bd5032625', 1, 'You are the junior doctor on the medical ward of a country hospital in South Australia, 90 minutes from the nearest tertiary centre, covering the ward and emergency department overnight with the GP on call by phone. A 79-year-old Aboriginal man with severe COPD and a hip fracture awaiting transfer has become hypoxic and delirious and cannot currently take part in decisions about escalation of his care. He has no advance care directive and no appointed guardian. Six family members are present; a man introduced as his nephew says he has always been the one who speaks for the old man and makes decisions with him, and that the patient''s only daughter lives in Adelaide and has had little contact for years. You need to decide who can lawfully consent on his behalf.', 'Which statement is correct under South Australian law?', '[{"id":"A","text":"A relative by Aboriginal kinship with a close and continuing relationship with him can be the person responsible"},{"id":"B","text":"Only his daughter, as his closest blood relative, can give consent, and she must be contacted before any decision"},{"id":"C","text":"The South Australian Civil and Administrative Tribunal must appoint a guardian before any medical decision can be made"},{"id":"D","text":"Decisions about limiting treatment cannot be made by family at all and rest solely with the treating consultant"}]'::jsonb, 'A', '{"A":"The Consent to Medical Treatment and Palliative Care Act 1995 (SA) sets out who may consent for an adult without capacity: a substitute decision-maker under an advance care directive, a guardian, then a prescribed relative, then an adult friend or carer. A relative includes a person related by blood, marriage, adoption or Aboriginal or Torres Strait Islander kinship rules who has a close and continuing relationship with the patient, so the nephew can be the person responsible.","B":"Blood proximity does not decide the matter; the Act requires a close and continuing relationship, and an estranged daughter does not automatically outrank a nephew who has acted for him for years.","C":"Tribunal involvement is reserved for disputes or situations with no suitable person responsible; the Act is designed to allow decisions by family without a tribunal order.","D":"The person responsible can consent to or refuse treatment on the patient''s behalf, guided by what the patient would have wanted; emergency treatment to save life can proceed without consent, but the family''s role in limitation decisions remains."}'::jsonb,
  'In South Australia, a relative under Aboriginal kinship rules with a close and continuing relationship can be the person responsible for consent when there is no advance care directive or guardian.', 'Overnight in a country hospital the junior doctor should phone the GP on call before any limitation decision, but can confidently involve the nephew as the person responsible rather than delaying while trying to reach a distant relative.', 'Aboriginal and Torres Strait Islander health', ARRAY['Professionalism, ethics and law','Palliative care and goals of care','Rural and remote']::text[], ARRAY['1.3','1.2','2.1']::text[],
  'family and kinship in decision-making', 'ward', 'recall', '{"age_band":"75-84","sex":"male","indigenous":true}'::jsonb, 2,
  'sa', 'ai', NULL, '[{"source":"sa_health","title":"Consent to Medical Treatment and Palliative Care Act 1995 (SA) and SA Health Consent to Medical Treatment and Health Care Policy","locator":"Person responsible; definition of relative","supports":"key"},{"source":"sa_health","title":"Advance Care Directives Act 2013 (SA)","locator":"Substitute decision-makers","supports":"key"}]'::jsonb,
  'Key facts: SA hierarchy is advance care directive substitute decision-maker, then guardian, then prescribed relative (spouse or domestic partner, adult related by blood, marriage, adoption or Aboriginal or Torres Strait Islander kinship rules, with a close and continuing relationship), then adult friend or carer. Decisions must reflect what the patient would have wanted. Emergency life-saving treatment can be given without consent. Common misconception: that next of kin is a legal status based on closeness of blood relationship. Out of scope: process for SACAT guardianship applications.', 'none', ARRAY[]::text[], NULL, NULL,
  'both', ARRAY['C']::text[], 'rural'
  
ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO item (id, status, calibration_core, current_version) VALUES ('4160ede6-4257-ae5b-8a2a-70579b7d630d', 'live', true, 1)
  ON CONFLICT (id) DO NOTHING;
INSERT INTO item_version (item_id, version, stem, lead_in, options, key, explanations, learning_point, rural_note,
  learning_area, secondary_areas, domains, presentation, context, cognitive_level, patient, target_difficulty,
  jurisdiction, provenance, generation, "references", tutor_context, review_level, reviewed_by, review_by, supersedes,
  pgy_level, clinical_experiences, setting)
SELECT '4160ede6-4257-ae5b-8a2a-70579b7d630d', 1, 'You are the intern in the emergency department of a metropolitan general hospital on an afternoon shift, with the registrar available. A 52-year-old Aboriginal man has had a forearm laceration sutured and is ready to go home. His observations show blood pressure 168/98 mmHg on two readings, he has a body mass index of 34, smokes 15 cigarettes a day and mentions that his father had a heart attack at 50. He says he has not seen a doctor for "years", does not have a regular GP, and that scripts are expensive so he usually does not fill them. He is asymptomatic and his ECG is normal. The hospital''s Aboriginal Liaison Officer is on duty.', 'What is the most appropriate action to address his longer-term health?', '[{"id":"A","text":"Prescribe amlodipine on a hospital script and advise him to see a GP at some point in the future for review"},{"id":"B","text":"Refer him to the hospital''s cardiology outpatient clinic for a specialist assessment of his hypertension"},{"id":"C","text":"Link him to an Aboriginal health service or GP for a health assessment and Closing the Gap PBS registration"},{"id":"D","text":"Admit him under the general medical team for further investigation and control of his blood pressure"}]'::jsonb, 'C', '{"A":"Starting an antihypertensive from the emergency department without follow-up, for a man who says he cannot afford scripts and has no GP, is unlikely to achieve anything and may expose him to unmonitored side effects.","B":"Uncomplicated hypertension does not need a specialist clinic; it needs continuity of primary care where his overall cardiovascular risk, smoking and weight can be managed over time.","C":"He has multiple cardiovascular risk factors and the main barrier is access to affordable primary care. The Medicare health assessment for Aboriginal and Torres Strait Islander people (item 715) is the entry point to structured risk management, and registration for the Closing the Gap PBS co-payment measure, which is done through a general practice or Aboriginal health service, removes or reduces the cost of his medicines. The Aboriginal Liaison Officer can make the connection and a warm referral far more likely to succeed.","D":"Asymptomatic hypertension without end-organ damage is not an indication for admission; it would use an acute bed without solving his lack of ongoing care."}'::jsonb,
  'For an Aboriginal patient without primary care, the most useful emergency department intervention for chronic disease risk is a warm referral to an Aboriginal health service or GP for a health assessment and Closing the Gap PBS registration.', 'In a regional hospital the Aboriginal health team or local Aboriginal Community Controlled Health Service plays the same role; the intern may need to phone the service directly.', 'Aboriginal and Torres Strait Islander health', ARRAY['Chronic disease, prevention and advocacy','Discharge planning']::text[], ARRAY['1.3','3.1','4.4']::text[],
  'health assessment and Closing the Gap PBS', 'ed', 'management', '{"age_band":"45-64","sex":"male","indigenous":true}'::jsonb, 3,
  'national', 'ai', NULL, '[{"source":"other","title":"Department of Health and Aged Care, Closing the Gap PBS Co-payment Program and MBS item 715 (Aboriginal and Torres Strait Islander Health Assessment)","locator":"Eligibility and registration","supports":"key"},{"source":"red_book","title":"RACGP National guide to preventive healthcare for Aboriginal and Torres Strait Islander people (4th edition)","locator":"Cardiovascular disease prevention","supports":"key"}]'::jsonb,
  'Key facts: Aboriginal and Torres Strait Islander people are eligible for an annual 715 health assessment from birth; absolute cardiovascular risk assessment is recommended from age 30 (and from 18 in some guidance). Closing the Gap PBS co-payment registration is a one-off registration through a practice; hospital doctors cannot register patients but can prescribe CTG scripts once registered. Common misconception: that the emergency department''s job ends at the acute problem. Out of scope: antihypertensive selection.', 'none', ARRAY[]::text[], NULL, NULL,
  'PGY1', ARRAY['B']::text[], 'metro'
  
ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO item (id, status, calibration_core, current_version) VALUES ('e454021a-7521-269b-7523-b960c82b9ca5', 'live', true, 1)
  ON CONFLICT (id) DO NOTHING;
INSERT INTO item_version (item_id, version, stem, lead_in, options, key, explanations, learning_point, rural_note,
  learning_area, secondary_areas, domains, presentation, context, cognitive_level, patient, target_difficulty,
  jurisdiction, provenance, generation, "references", tutor_context, review_level, reviewed_by, review_by, supersedes,
  pgy_level, clinical_experiences, setting)
SELECT 'e454021a-7521-269b-7523-b960c82b9ca5', 1, 'You are the intern in the emergency department of a tertiary hospital in Adelaide. A 34-year-old Aboriginal woman from the APY Lands, whose first language is Pitjantjatjara and who speaks limited English, has presented with 12 hours of right lower abdominal pain. She is haemodynamically stable with localised tenderness. The surgical registrar has reviewed her and asks you to obtain consent for a CT abdomen and, depending on the result, an appendicectomy, and to do this quickly because the CT slot is in 30 minutes. Her 12-year-old son, who speaks English well, has been translating so far. The Aboriginal Liaison Officer is on site, and the hospital has access to telephone and video interpreting services.', 'What is the most important step to take before the consent discussion?', '[{"id":"A","text":"Proceed with her son interpreting, since he has already been doing so and time matters"},{"id":"B","text":"Book a Pitjantjatjara interpreter through the telephone or video interpreting service"},{"id":"C","text":"Ask the Aboriginal Liaison Officer to interpret the consent discussion for her"},{"id":"D","text":"Ask a ward nurse who speaks some Pitjantjatjara to explain the procedure to her"}]'::jsonb, 'B', '{"A":"Children must not be used as interpreters for clinical decisions: it places an unfair burden on the child, risks inaccurate translation of medical content and compromises her privacy. Her condition is stable and a short delay to arrange an interpreter is safe.","B":"Valid consent requires that she understands the nature, risks and alternatives of the procedure in a language she commands. An accredited interpreter (the Interpreting and Translating Centre or the national service) provides this, and the Aboriginal Liaison Officer can support her, help with family contact and cultural safety, but does not replace the interpreter. Pitjantjatjara interpreters are limited, so the request should be made now.","C":"Aboriginal Liaison Officers provide cultural and practical support; unless they are an accredited interpreter in the relevant language they should not be used to interpret clinical consent, and asking them to do so blurs their role.","D":"Partial language skills in a staff member are not adequate for consent to surgery; misunderstanding of risks or alternatives is likely."}'::jsonb,
  'Consent for an investigation or operation in a patient with limited English requires an accredited interpreter; family members, children and Aboriginal Liaison Officers should not interpret clinical consent.', '', 'Aboriginal and Torres Strait Islander health', ARRAY['Communication, handover and consent','Surgery and perioperative care']::text[], ARRAY['1.3','1.2','2.8']::text[],
  'language and interpreter needs', 'ed', 'prioritisation', '{"age_band":"25-44","sex":"female","indigenous":true}'::jsonb, 3,
  'national', 'ai', NULL, '[{"source":"sa_health","title":"SA Health Consent to Medical Treatment and Health Care Policy and SA Health Interpreter Services guideline","locator":"Use of accredited interpreters for consent","supports":"key"},{"source":"acsqhc","title":"National Safety and Quality Health Service Standards (2nd edition)","locator":"Partnering with Consumers Standard, Action 2.6 and 2.8","supports":"key"}]'::jsonb,
  'Key facts: an accredited interpreter should be used for any significant clinical communication, especially consent, when the patient is not proficient in English; in SA this is through the Interpreting and Translating Centre or the national Translating and Interpreting Service, with Aboriginal language interpreters available via specialist services. Children and relatives should not interpret except in a life-threatening emergency when no alternative exists. Common misconception: that the Aboriginal Liaison Officer is an interpreter. Out of scope: imaging choice in suspected appendicitis.', 'none', ARRAY[]::text[], NULL, NULL,
  'PGY1', ARRAY['A']::text[], 'any'
  
ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO item (id, status, calibration_core, current_version) VALUES ('55e951c5-eced-d0c8-79db-1796b312bb95', 'live', true, 1)
  ON CONFLICT (id) DO NOTHING;
INSERT INTO item_version (item_id, version, stem, lead_in, options, key, explanations, learning_point, rural_note,
  learning_area, secondary_areas, domains, presentation, context, cognitive_level, patient, target_difficulty,
  jurisdiction, provenance, generation, "references", tutor_context, review_level, reviewed_by, review_by, supersedes,
  pgy_level, clinical_experiences, setting)
SELECT '55e951c5-eced-d0c8-79db-1796b312bb95', 1, 'You are the PGY2 covering the ward and the emergency department overnight at a country hospital 90 minutes from the nearest tertiary centre, with the GP on call by phone. At 02:00 the nurse tells you a 29-year-old Aboriginal woman has arrived with abdominal pain, triaged category 4. The nurse adds, "She''s back again, third time this fortnight, the notes say drug-seeking." Her previous two visits ended with analgesia and discharge without investigations; the notes record no examination findings. Her observations tonight are heart rate 108 beats per minute, temperature 37.9 degrees Celsius, blood pressure 118/70 mmHg. You have one other patient, a man with stable chest pain awaiting a repeat troponin in an hour.', 'What is the most appropriate priority?', '[{"id":"A","text":"Review her previous notes, offer analgesia as on earlier visits and discharge her with advice to see the GP"},{"id":"B","text":"Ask the nurse to contact the GP on call to see her in the morning so you can focus on the chest pain patient"},{"id":"C","text":"Request a urine drug screen before deciding whether analgesia is appropriate for her tonight"},{"id":"D","text":"Assess her now as a new presentation, with a full history, examination and relevant investigations"}]'::jsonb, 'D', '{"A":"Repeating the earlier approach anchors on a label that was never supported by documented assessment; repeat presentations with tachycardia and low-grade fever raise the likelihood of a missed diagnosis such as pelvic inflammatory disease, ectopic pregnancy or appendicitis.","B":"Deferring a febrile, tachycardic patient to the morning is not safe; the chest pain patient is stable and awaiting a timed test, so she can and should be seen now.","C":"A drug screen does not help diagnose abdominal pain and signals that the clinician has already decided the presentation is not genuine; it entrenches bias and delays care.","D":"Labels such as \"drug-seeking\" in the records of Aboriginal patients are a recognised form of systemic bias and are associated with under-investigation and worse outcomes. Her repeated attendance and abnormal observations demand a complete assessment, including pregnancy test and bloods, as for any patient, and an honest documented plan."}'::jsonb,
  'Repeat presentations with abnormal observations require a full fresh assessment; prior labels such as "drug-seeking" are a risk factor for missed diagnosis, not a diagnosis.', 'In a country hospital the junior doctor is often the only clinician who can break a cycle of unexamined repeat presentations; if serious pathology is suspected, early discussion with the GP on call and the tertiary surgical or gynaecology registrar about transfer is appropriate.', 'Aboriginal and Torres Strait Islander health', ARRAY['Emergency presentations','Patient safety, quality and systems','Rural and remote']::text[], ARRAY['3.4','1.4','2.8']::text[],
  'systemic racism and health inequity', 'rural', 'prioritisation', '{"age_band":"25-44","sex":"female","indigenous":true}'::jsonb, 2,
  'national', 'ai', NULL, '[{"source":"mba","title":"Medical Board of Australia, Good medical practice: a code of conduct for doctors in Australia","locator":"Section 4.7 Aboriginal and Torres Strait Islander health and cultural safety; section 2.1 providing good care","supports":"key"},{"source":"acsqhc","title":"National Safety and Quality Health Service Standards, User guide for Aboriginal and Torres Strait Islander health","locator":"Addressing institutional racism","supports":"key"}]'::jsonb,
  'Key facts: institutional racism manifests as lower rates of investigation, analgesia and admission for Aboriginal patients with the same presentations; frequent presentation is a red flag for an unmet need. Judgemental labels in notes propagate through episodes. Common misconception: that prior attendances without a diagnosis make serious disease less likely. Out of scope: the differential diagnosis workup itself.', 'none', ARRAY[]::text[], NULL, NULL,
  'PGY2', ARRAY['A']::text[], 'rural'
  
ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO item (id, status, calibration_core, current_version) VALUES ('5310fbc7-03d4-7842-60f4-f1634e72db14', 'live', true, 1)
  ON CONFLICT (id) DO NOTHING;
INSERT INTO item_version (item_id, version, stem, lead_in, options, key, explanations, learning_point, rural_note,
  learning_area, secondary_areas, domains, presentation, context, cognitive_level, patient, target_difficulty,
  jurisdiction, provenance, generation, "references", tutor_context, review_level, reviewed_by, review_by, supersedes,
  pgy_level, clinical_experiences, setting)
SELECT '5310fbc7-03d4-7842-60f4-f1634e72db14', 1, 'You are the intern at a regional hospital with a small medical ward and no intensive care unit, making a telehealth follow-up call one week after discharge to a 79-year-old woman who was admitted with an exacerbation of COPD. She is recovering well on her usual inhalers and lives independently in a town 40 minutes away. She asks about vaccinations because her neighbour "caught shingles and was in agony". You confirm from the Australian Immunisation Register that she received this year''s influenza vaccine and her COVID-19 booster in the last six months, but there is no record of pneumococcal or zoster vaccination. She has no history of immunosuppression and no allergies, and is happy to see her GP.', 'What is the most appropriate advice?', '[{"id":"A","text":"Reassure her that the influenza and COVID-19 vaccines are the only vaccines recommended at her age"},{"id":"B","text":"Advise that pneumococcal vaccination is unlikely to benefit her now that she is over 75 years of age"},{"id":"C","text":"Recommend she see her GP for funded pneumococcal and two-dose recombinant zoster vaccination"},{"id":"D","text":"Advise against the zoster vaccine because inhaled corticosteroids make a live vaccine unsafe"}]'::jsonb, 'C', '{"A":"The Australian Immunisation Handbook recommends several additional vaccines for older adults, including pneumococcal and zoster vaccination, and an admission for COPD is a good prompt to catch up.","B":"Adults aged 70 years and over without prior pneumococcal vaccination are recommended and funded to receive it; COPD further increases her risk of pneumococcal pneumonia and invasive disease.","C":"The Handbook recommends pneumococcal vaccination for all adults from 70 years, and the recombinant zoster vaccine (two doses, 2 to 6 months apart) for adults from 65 years; both are funded on the National Immunisation Program for her. Her GP can give them and record them on the Australian Immunisation Register.","D":"The recombinant zoster vaccine is not a live vaccine and is safe with inhaled corticosteroids; the earlier live zoster vaccine is no longer in use in Australia."}'::jsonb,
  'A hospital contact with an older adult is an opportunity to check the Australian Immunisation Register and recommend funded pneumococcal and recombinant zoster vaccination.', '', 'Chronic disease, prevention and advocacy', ARRAY['Telehealth','Older people, delirium and falls','General medicine']::text[], ARRAY['3.1','3.2']::text[],
  'adult immunisation', 'telehealth', 'management', '{"age_band":"75-84","sex":"female","indigenous":false}'::jsonb, 2,
  'national', 'ai', NULL, '[{"source":"immunisation_handbook","title":"Australian Immunisation Handbook","locator":"Pneumococcal disease; Zoster (herpes zoster); Vaccination for older adults","supports":"key"}]'::jsonb,
  'Key facts: National Immunisation Program funds pneumococcal vaccination for non-Indigenous adults from 70 years (from 50 years for Aboriginal and Torres Strait Islander adults) and recombinant zoster vaccine (Shingrix, two doses) from 65 years (from 50 years for Aboriginal and Torres Strait Islander adults and for immunocompromised adults from 18). Respiratory syncytial virus vaccination is also recommended from 75 years. Common misconception: that zoster vaccine is live and contraindicated with steroids. Out of scope: COVID-19 booster intervals.', 'none', ARRAY[]::text[], NULL, NULL,
  'PGY1', ARRAY['B']::text[], 'any'
  
ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO item (id, status, calibration_core, current_version) VALUES ('1eb0db42-5421-d2c9-14ec-b493b7723d4c', 'live', true, 1)
  ON CONFLICT (id) DO NOTHING;
INSERT INTO item_version (item_id, version, stem, lead_in, options, key, explanations, learning_point, rural_note,
  learning_area, secondary_areas, domains, presentation, context, cognitive_level, patient, target_difficulty,
  jurisdiction, provenance, generation, "references", tutor_context, review_level, reviewed_by, review_by, supersedes,
  pgy_level, clinical_experiences, setting)
SELECT '1eb0db42-5421-d2c9-14ec-b493b7723d4c', 1, 'You are the intern in the outpatient clinic of a 30-bed regional hospital in South Australia''s Mid North, 2 hours by road from Adelaide, seeing patients before the visiting surgeon''s list. A 38-year-old man who farms near the town is being worked up for elective inguinal hernia repair. In the pre-admission questionnaire he reports drinking six to eight stubbies of full-strength beer on four nights a week and his AUDIT-C score is 8 out of 12. He has never had withdrawal symptoms, seizures or blackouts, does not drink in the morning and has had no injuries or legal problems related to alcohol. His gamma-glutamyl transferase is 92 U/L and other liver tests are normal. He says "everyone around here drinks like that".', 'Which interpretation of his drinking is most accurate?', '[{"id":"A","text":"He has alcohol dependence and will require inpatient withdrawal management before his surgery can be scheduled"},{"id":"B","text":"He is drinking at a risky level above Australian guidelines, warranting brief intervention and withdrawal planning"},{"id":"C","text":"His intake is within the Australian guideline of no more than 10 standard drinks a week and no action is needed"},{"id":"D","text":"His raised gamma-glutamyl transferase indicates established alcoholic liver disease needing hepatology referral first"}]'::jsonb, 'B', '{"A":"Dependence is defined by features such as tolerance, withdrawal, loss of control and continued use despite harm; he reports none of these, so inpatient withdrawal management is not indicated, although peri-operative monitoring for withdrawal is sensible.","B":"Six to eight full-strength stubbies is about 8 to 11 standard drinks per occasion and 30 to 45 per week, far above the National Health and Medical Research Council guideline of no more than 10 standard drinks a week and no more than 4 on any one day. An AUDIT-C of 8 indicates risky drinking. A brief intervention using feedback, advice and goal-setting is effective at this level and the anaesthetist should know about his intake.","C":"This misreads the guideline; his weekly intake is three to four times the recommended maximum and his per-occasion intake exceeds the daily limit each time he drinks.","D":"An isolated mildly raised gamma-glutamyl transferase is a marker of heavy drinking, not of established liver disease; with normal other liver tests it does not warrant specialist referral or delay of surgery."}'::jsonb,
  'Six to eight full-strength beers four nights a week is risky drinking well above the Australian guideline, warranting a brief intervention and peri-operative withdrawal planning, not a dependence label.', 'In a regional town with high local drinking norms, framing the discussion around the guideline numbers and his own goals is more effective than moral judgement; the local drug and alcohol service and the national Alcohol and Drug Information Service (1300 13 1340 in SA) can provide follow-up support.', 'Chronic disease, prevention and advocacy', ARRAY['Surgery and perioperative care','Rural and remote','Anaesthetics']::text[], ARRAY['3.1','3.2','1.4']::text[],
  'alcohol brief intervention', 'clinic', 'interpretation', '{"age_band":"25-44","sex":"male","indigenous":false}'::jsonb, 2,
  'national', 'ai', NULL, '[{"source":"other","title":"National Health and Medical Research Council, Australian guidelines to reduce health risks from drinking alcohol (2020)","locator":"Guideline 1: adults","supports":"key"},{"source":"etg","title":"Therapeutic Guidelines: Addiction","locator":"Screening for alcohol use; brief intervention","supports":"key"}]'::jsonb,
  'Key facts: a full-strength 375 mL stubby is about 1.4 standard drinks; AUDIT-C of 4 or more in men (3 in women) suggests risky drinking, higher scores are more concerning but do not by themselves diagnose dependence. Brief intervention (FLAGS: feedback, listen, advice, goals, strategies) is effective in non-dependent risky drinkers. Pre-operatively, heavy drinkers have higher complication rates and may need withdrawal monitoring and thiamine. Common misconception: that any heavy drinker is dependent, or that normal transaminases exclude a drinking problem. Out of scope: pharmacotherapy for alcohol dependence.', 'none', ARRAY[]::text[], NULL, NULL,
  'PGY1', ARRAY['B','D']::text[], 'rural'
  
ON CONFLICT (item_id, version) DO NOTHING;
COMMIT;
